/* static/css/style.css */

/* General Styles */
body {
  font-family: Arial, sans-serif;
  background-color: #f8f9fa;
  margin: 0;
  padding: 0;
}

/* Navigation Bar */
.navbar {
  background-color: #343a40;
  color: #ffffff;
  padding: 10px 20px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.navbar a {
  color: #ffffff;
  text-decoration: none;
  margin: 0 15px;
}

.navbar a:hover {
  text-decoration: underline;
}

/* Header Section */
header {
  text-align: center;
  padding: 50px 20px;
  background-color: #007bff;
  color: #ffffff;
}

header h1 {
  font-size: 2.5em;
  margin-bottom: 10px;
}

header p {
  font-size: 1.2em;
}

/* Main Content */
main {
  padding: 20px;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
}

/* Problem List */
.problem-list {
  list-style: none;
  padding: 0;
}

.problem-list li {
  background-color: #ffffff;
  border: 1px solid #ddd;
  margin-bottom: 10px;
  padding: 15px;
  border-radius: 5px;
  display: flex;
  justify-content: space-between;
}

.problem-list li:hover {
  background-color: #f1f1f1;
}

.problem-list .title {
  font-weight: bold;
}

.problem-list .difficulty {
  color: #007bff;
  font-weight: bold;
}

/* Forms */
form {
  max-width: 600px;
  margin: 20px auto;
  background-color: #ffffff;
  padding: 20px;
  border: 1px solid #ddd;
  border-radius: 5px;
}

form input,
form textarea,
form select {
  width: 100%;
  padding: 10px;
  margin-bottom: 15px;
  border: 1px solid #ddd;
  border-radius: 5px;
}

form button {
  background-color: #007bff;
  color: #ffffff;
  padding: 10px 15px;
  border: none;
  border-radius: 5px;
  cursor: pointer;
}

form button:hover {
  background-color: #0056b3;
}

/* Footer */
footer {
  text-align: center;
  padding: 20px;
  background-color: #343a40;
  color: #ffffff;
}

footer a {
  color: #ffffff;
  text-decoration: none;
}

footer a:hover {
  text-decoration: underline;
}

/* Leaderboard */
.leaderboard {
  margin: 20px auto;
  max-width: 800px;
  border-collapse: collapse;
  text-align: left;
}

.leaderboard th,
.leaderboard td {
  padding: 10px;
  border: 1px solid #ddd;
}

.leaderboard th {
  background-color: #007bff;
  color: #ffffff;
}

.leaderboard tr:nth-child(even) {
  background-color: #f8f9fa;
}

// static/js/app.js

// Function to fetch problem data from the server
async function fetchProblemData(problemId) {
    try {
        const response = await fetch(`/api/problems/${problemId}`);
        if (!response.ok) {
            throw new Error('Failed to fetch problem data');
        }
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error fetching problem data:', error);
    }
}

// Function to submit a solution for evaluation
async function submitSolution(problemId, solutionCode) {
    try {
        const response = await fetch(`/api/submit`, {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                problem_id: problemId,
                solution_code: solutionCode
            })
        });

        if (!response.ok) {
            throw new Error('Failed to submit solution');
        }

        const result = await response.json();
        return result;
    } catch (error) {
        console.error('Error submitting solution:', error);
    }
}

// Function to update leaderboard data
async function fetchLeaderboardData() {
    try {
        const response = await fetch(`/api/leaderboard`);
        if (!response.ok) {
            throw new Error('Failed to fetch leaderboard data');
        }
        const data = await response.json();
        return data;
    } catch (error) {
        console.error('Error fetching leaderboard data:', error);
    }
}

// Function to display problem details on the frontend
function displayProblem(problemData) {
    const problemContainer = document.getElementById('problem-container');
    if (!problemContainer) return;

    problemContainer.innerHTML = `
        <h2>${problemData.title}</h2>
        <p>${problemData.description}</p>
        <pre>${problemData.input_format}</pre>
        <pre>${problemData.output_format}</pre>
    `;
}

// Function to handle solution submission
async function handleSubmit(event) {
    event.preventDefault();

    const problemId = document.getElementById('problem-id').value;
    const solutionCode = document.getElementById('solution-code').value;

    const result = await submitSolution(problemId, solutionCode);

    if (result) {
        const resultContainer = document.getElementById('result-container');
        resultContainer.textContent = `Result: ${result.message}`;
    }
}

// Initialize event listeners after DOM content is loaded
document.addEventListener('DOMContentLoaded', () => {
    const submitButton = document.getElementById('submit-button');
    if (submitButton) {
        submitButton.addEventListener('click', handleSubmit);
    }

    const problemId = document.getElementById('problem-id')?.value;
    if (problemId) {
        fetchProblemData(problemId).then(displayProblem);
    }
});

from flask import Blueprint, render_template, request, redirect, url_for, flash
from app.database import db
from app.models.problem import Problem

problem_bp = Blueprint('problem', __name__)

@problem_bp.route('/problems', methods=['GET'])
def list_problems():
    # Fetch all problems from the database
    problems = Problem.query.all()
    return render_template('problem.html', problems=problems)

@problem_bp.route('/problems/<int:problem_id>', methods=['GET'])
def view_problem(problem_id):
    # Fetch a specific problem by ID
    problem = Problem.query.get_or_404(problem_id)
    return render_template('submit.html', problem=problem)

@problem_bp.route('/problems/new', methods=['GET', 'POST'])
def create_problem():
    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')
        difficulty = request.form.get('difficulty')

        if not title or not description or not difficulty:
            flash('All fields are required!', 'error')
            return redirect(url_for('problem.create_problem'))

        # Create and save new problem
        new_problem = Problem(title=title, description=description, difficulty=difficulty)
        db.session.add(new_problem)
        db.session.commit()
        flash('Problem created successfully!', 'success')
        return redirect(url_for('problem.list_problems'))

    return render_template('index.html')

@problem_bp.route('/problems/<int:problem_id>/edit', methods=['GET', 'POST'])
def edit_problem(problem_id):
    problem = Problem.query.get_or_404(problem_id)

    if request.method == 'POST':
        problem.title = request.form.get('title')
        problem.description = request.form.get('description')
        problem.difficulty = request.form.get('difficulty')

        if not problem.title or not problem.description or not problem.difficulty:
            flash('All fields are required!', 'error')
            return redirect(url_for('problem.edit_problem', problem_id=problem_id))

        # Update and save problem
        db.session.commit()
        flash('Problem updated successfully!', 'success')
        return redirect(url_for('problem.view_problem', problem_id=problem_id))

    return render_template('index.html', problem=problem)

@problem_bp.route('/problems/<int:problem_id>/delete', methods=['POST'])
def delete_problem(problem_id):
    problem = Problem.query.get_or_404(problem_id)

    # Delete the problem
    db.session.delete(problem)
    db.session.commit()
    flash('Problem deleted successfully!', 'success')
    return redirect(url_for('problem.list_problems'))

from flask import Blueprint, request, jsonify, render_template
from sqlalchemy.exc import SQLAlchemyError
from app.database import db
from app.models.user import User

user_bp = Blueprint('user', __name__)

@user_bp.route('/users', methods=['GET'])
def list_users():
    try:
        users = User.query.all()
        return jsonify([user.to_dict() for user in users]), 200
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['GET'])
def view_user(user_id):
    try:
        user = User.query.get(user_id)
        if user is None:
            return jsonify({'error': 'User not found'}), 404
        return jsonify(user.to_dict()), 200
    except SQLAlchemyError as e:
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users', methods=['POST'])
def create_user():
    try:
        data = request.get_json()
        if not data or not data.get('username') or not data.get('email'):
            return jsonify({'error': 'Invalid input'}), 400
        new_user = User(username=data['username'], email=data['email'])
        db.session.add(new_user)
        db.session.commit()
        return jsonify(new_user.to_dict()), 201
    except SQLAlchemyError as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['PUT'])
def edit_user(user_id):
    try:
        user = User.query.get(user_id)
        if user is None:
            return jsonify({'error': 'User not found'}), 404
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid input'}), 400
        user.username = data.get('username', user.username)
        user.email = data.get('email', user.email)
        db.session.commit()
        return jsonify(user.to_dict()), 200
    except SQLAlchemyError as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

@user_bp.route('/users/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    try:
        user = User.query.get(user_id)
        if user is None:
            return jsonify({'error': 'User not found'}), 404
        db.session.delete(user)
        db.session.commit()
        return jsonify({'message': 'User deleted'}), 200
    except SQLAlchemyError as e:
        db.session.rollback()
        return jsonify({'error': str(e)}), 500

